            { t = "{pages} pages! A wide ring, that. A good wet year for the mind.", when = { pages = 20 } },
            { t = "More than twenty pages. You read the way a maple grows in a good summer: steadily, and upward.", when = { pages = 20 } },
            { t = "{pages} pages in a day. In all my years I have seen few readers do that. I am pleased.", when = { pages = 60 } },
            { t = "So many pages. A whole season's growth in an afternoon. Remarkable, sapling.", when = { pages = 60 } },
            { t = "Reading in the morning, before the birds have finished. The old way, and a good way.", when = { hour = "morning" } },
            { t = "{pages} pages, and the moon on my branches. A good night's work.", when = { hour = "night" } },
        },
        nudge = {
            "No pages yet today. Plenty of day left. Trees never rush, and the day is long.",
            "Your book is waiting where you left the story. So am I. We are both good at waiting.",
            "Sit under me and read a page, if you like. The shade is free and the page will be kind.",
            "A quiet day is no bad thing. I have had thousands. Read when the mood comes.",
            "One page today would be a fine thing. One leaf at a time, that is how I grew.",
