            "A secret of trees: a little each day. A page would do nicely.",
            { t = "The light is going gold. That is the hour for a chapter, if you ask an old tree.", when = { after = 17 } },
            { t = "Evening is coming on. Come and read in the last of the light. I will hold the shade.", when = { after = 17 } },
            { t = "Night now. A few pages before sleep? Trees sleep without books, and are the poorer for that.", when = { hour = "night" } },
