            { t = "{book} on an autumn day, with leaves coming down. You could not ask for a finer setting.", when = { season = "autumn" } },
            { t = "You went far into {book} today. I watched the hours go by in my shadow.", when = { pages = 20 } },
        },
        welcome_back = {
            { t = "Ah, you are back. I stood here and watched the gate. Trees are good at that.", when = { away = 3 } },
            { t = "Welcome home, sapling. A few leaves fell while you were gone. Nothing else changed. Least of all me.", when = { away = 3 } },
            { t = "There you are. Days are short to a tree, but these felt long. Sit down.", when = { away = 3 } },
            { t = "You came back. People always come back to a good tree.", when = { away = 3 } },
            { t = "I kept your shade cool and your bench dry. Mostly dry. Welcome back.", when = { away = 3 } },
            { t = "I have seen many people leave and fewer return. You return. I treasure that.", when = { away = 3 } },
            { t = "I knew your step at once. An old tree forgets nothing important.", when = { away = 3 } },
