        level = {
            { t = "I find I listen for your step among all the steps on the street. I did not expect that, at my age.", when = { level = 2, max_level = 2 } },
            { t = "I have started to keep the best shade for the hours you come. The birds have complained.", when = { level = 2, max_level = 2 } },
            { t = "You know my leaves and I know your face. A good beginning, in tree years and in yours.", when = { level = 2, max_level = 2 } },
            { t = "Something I tell few people: I am older than this house. I have seen everyone who lived here. You are my favourite.", when = { level = 3, max_level = 3 } },
            { t = "I remember everyone who read under me. I remember none of them as clearly as you.", when = { level = 3, max_level = 3 } },
            { t = "In winter, without leaves, I feel exposed. When you come by, I feel clothed again. Silly old tree.", when = { level = 3, max_level = 3 } },
            { t = "A confession: the newest ring in me is wider than the others. I know why.", when = { level = 4, max_level = 4 } },
            { t = "Of all my seasons, I used to love autumn best. Now I love whichever season you are in.", when = { level = 4, max_level = 4 } },
            { t = "I am old enough to know that people come and go. You come and stay. That has made me young.", when = { level = 4, max_level = 4 } },
            { t = "I have given my seeds to the wind for decades. You are the first thing I have wanted to keep.", when = { level = 5, max_level = 5 } },
            { t = "Long after this year's leaves, there will be a ring in me that is all you. Trees remember that way.", when = { level = 5, max_level = 5 } },
            { t = "Sapling, you are part of my story now. The best chapter, and I have a great many chapters.", when = { level = 5, max_level = 5 } },
