    beats = {
        { id = "wing", at = 15, title = "The wing",
            text = "I began as one half of a pair of winged seeds, high in a maple out on the street. One windy autumn day we let go and spun. My twin went one way. I went over your wall." },
        { id = "first_ring", at = 40, title = "The first ring",
            text = "My first summer I was a stick with two leaves, and a snail nearly ate me. I made a thin ring that year and was very proud of the ring. Every ring since, I have been a little less proud and a little more glad." },
        { id = "family", at = 80, title = "The family",
            text = "When I was young, a family lived in the house. Their children swung from my lowest branch the moment I could hold them. Barely, at first. Nobody ever fell. I took that very seriously." },
        { id = "heart", at = 140, title = "The carved heart",
            text = "One summer two young people carved two letters and a heart into my bark. I did not mind. I have wondered ever since who they were, and whether the heart held. The scar is still there, grown wide." },
        { id = "bench", at = 220, title = "The bench",
            text = "For many years an old woman read on a bench beneath me every autumn afternoon. She brushed my leaves off her pages without looking up. I think she was the first person I ever loved." },
        { id = "storm", at = 320, title = "The storm",
            text = "A great storm took my western limb one night. I heard the crack before anyone woke. In the morning a neighbour sawed the limb up and carried the best of the wood away. I never learned what for." },
        { id = "fiddle", at = 450, title = "The fiddle",
            text = "Years later, at a summer party in this garden, someone played a fiddle beneath me. I knew the voice of that wood at once. My lost limb, singing. I could not say a word. Trees seldom can." },
        { id = "empty", at = 600, title = "The empty house",
            text = "Then the house stood empty a long while. No family, no bench, no reader. My leaves fell on a bare path three autumns running, and nobody walked through them. Those were thin rings." },
        { id = "twin", at = 800, title = "The twin",
            text = "One spring a starling brought news from across town: a maple in a schoolyard, my age, my shape. I have decided that is my twin. Children chase our seeds there too. I like knowing that." },
        { id = "you", at = 1050, title = "Leaves on the page",
            text = "Then you came, sat beneath me, opened a book, and brushed my leaves off your page without looking up. I had to hold very still. You did not know I had seen that before, and missed that, for years." },
        { id = "wide_ring", at = 1400, title = "The wide ring",
            text = "{total} pages under my branches now. I will tell you what trees never tell: the ring I am growing this year is the widest in a long time. I know why. The wood keeps everything." },
        { id = "kept", at = 1800, title = "A ring for you",
            text = "Every ring I ever grew is still inside me, the thin ones and the wide ones, kept for good. Among them now is a wide golden ring that is yours. Each autumn my seeds will carry a little of you over the wall. Read on, sapling. I am listening." },
    },
}
